def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        # Find a horizontal run of at least five non-background cells
        # followed only by background cells, and mark the remaining tail.
        bg = max(set(row), key=row.count)
        i = 0
        while i < len(row):
            if row[i] == bg:
                i += 1
                continue
            j = i
            while j < len(row) and row[j] == row[i]:
                j += 1
            if j - i >= 5 and all(v == bg for v in row[j:]):
                for k in range(j, len(row)):
                    out[grid.index(row)][k] = 1
                break
            i = j
    return out
