def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            end = c + 1
            while end < len(row) and row[end] == color:
                end += 1
            if end - c >= 5 and all(v == bg for v in row[end:]):
                for k in range(end, len(row)):
                    out[r][k] = 1
                break
            c = end
    return out
